/* Curt's script: the questions RegCollect's assistant is prepared to answer, written out in advance.
 * Each entry lists ways a user might ask (q), the answer (a), optional follow-up suggestions (next),
 * and optionally a page to open (go). Curt finds the best entry by meaning (word stems, related
 * words, and typo tolerance), so the questions do not have to be typed exactly as written here.
 * Curt also builds entries automatically from the doctrine library (every memo, case, statute,
 * court ruling, sanction type, outcome, agency, and source), so this file covers the app itself,
 * the rating rules, and a glossary of administrative-law terms.
 *
 * To teach Curt something new, add an entry. Keep answers short, plain, and accurate. */
window.CURT_SCRIPT = [
  // ------------------------------------------------------------------ the app
  { id: "about", q: ["what is regcollect", "what is this", "what is this app", "what is this website", "what does this app do", "what does regcollect do", "what is this site", "what is this for", "explain this app", "overview", "what am i looking at"],
    a: "RegCollect gathers what the federal executive branch publishes (rules, enforcement actions, adjudications, and presidential documents), sorts it by agency and kind of action, and flags actions that may be unlawful: unconstitutional, or beyond the powers the Constitution and Congress grant. Each flag is rated on one scale, lawfulness, by a published rubric and explains itself. It's built to help public-interest lawyers find actions worth challenging, so it also lists possible issues that need a closer look. It also tells you plainly what it could not see.",
    next: ["How are actions rated?", "What do you track?", "Take the tour"] },
  { id: "who_curt", q: ["who are you", "what are you", "are you ai", "are you chatgpt", "are you claude", "are you a robot", "who is curt", "why curt", "your name", "how does curt work", "how do you work", "how does the assistant work", "do you use chatgpt", "are you an ai"],
    a: "I'm Curt, RegCollect's built-in assistant. I'm a set of rules and a long script of prepared answers that runs entirely in your browser. I don't use any outside AI service and nothing you type leaves this page. I can operate the app, count and summarize what's in the data, and explain the rubric and the law it applies." },
  { id: "capabilities", q: ["what can you do", "help", "commands", "how do i use you", "what can i ask", "what should i ask", "examples", "give me ideas", "menu"],
    a: `Here are some things you can ask or tell me:<ul>
      <li><strong>Find things:</strong> “find IEEPA tariffs”, “search religious freedom rules since 2015”, “show FINRA expulsions”</li>
      <li><strong>Count and compare:</strong> “how many SEC actions are very likely unlawful?”, “which agency has the most rated issues in 2024?”, “compare the SEC and the FTC”</li>
      <li><strong>Top lists:</strong> “what are the most likely unlawful actions this year?”, “latest executive orders”, “what should I look at first?”</li>
      <li><strong>Briefings:</strong> “what's new?”, “what happened this week?”, “summarize the EPA”</li>
      <li><strong>Operate the app:</strong> “open the EPA”, “only rated actions”, “chart FDA sanctions by month”, “show what's new since October 1”, “mark everything as read”</li>
      <li><strong>Explain:</strong> “what does very likely mean?”, “what is Jarkesy?”, “what is the test for free exercise?”, “what is an NPRM?”, “why was the Clean Power Plan rated?”</li>
      <li><strong>Small things:</strong> the date and time, and arithmetic. I don't look anything up on other websites.</li></ul>` },
  { id: "tour", q: ["take the tour", "tutorial", "walk me through", "show me around", "guided tour", "how do i get started", "getting started", "new user"],
    a: "Starting the tour now. It takes about a minute and you can exit any time.", action: "tour" },
  { id: "manual", q: ["user manual", "instructions", "documentation", "where is the manual", "read the manual", "help page"],
    a: "The <a href=\"#manual\">user manual</a> covers every page. The <a href=\"#methods\">Methodology</a> page covers how ratings work.", go: "#manual" },
  { id: "directory", q: ["directory", "home page", "home screen", "start page", "where are the agencies", "agency buttons", "big buttons"],
    a: "The <a href=\"#home\">directory</a> is the home screen: a briefing of what's new since your last visit, then a button for the President, each federal agency, and each agency-controlled corporation, with its count of new actions and rated issues." },
  { id: "agency_page", q: ["agency page", "inside an agency", "activity tab", "charts tab", "coverage tab", "what are the tabs", "agency tabs"],
    a: "Each agency page has three tabs. <strong>Activity</strong> lists its actions (new since your last visit, the past 12 months, or everything since 2015), split by kind. <strong>Charts</strong> builds downloadable charts. <strong>Coverage</strong> shows which sources were checked and for which dates." },
  { id: "categories", q: ["kinds of action", "categories", "what is rulemaking", "what is enforcement", "what is adjudication", "what are other notices", "category meaning"],
    a: "Every action is sorted into one of five kinds: <strong>Rulemaking</strong> (proposed and final rules, guidance, and self-regulatory rule filings), <strong>Enforcement</strong> (charges, settlements, penalties), <strong>Adjudication and licensing</strong> (hearings, decisions, applications), <strong>Presidential actions</strong> (executive orders, proclamations, memoranda), and <strong>Other notices</strong> (meetings, paperwork, and the like)." },
  { id: "filter_box", q: ["filter box", "filter by words", "search within an agency", "filter actions", "narrow the list"],
    a: "On an agency's Activity tab, type in the filter box. Every word must match, but related words, other forms of a word, and word beginnings count (“tariff” also finds “duties”)." },
  { id: "only_rated", q: ["only flagged", "only rated", "hide unflagged", "only constitutional issues", "show only problems"],
    a: "Tick “Only rated constitutional issues” on an agency's Activity tab, or tell me “only rated actions” while you're on an agency page." },
  { id: "routine", q: ["routine fee filings", "why are fee filings hidden", "exchange fees", "show fee filings", "hidden items", "routine"],
    a: "Exchanges and clearing agencies file every fee change with the SEC, which publishes thousands of them. They're labeled routine and hidden unless you tick “Include routine fee filings” (on the exchanges page or in Research)." },
  { id: "corporations", q: ["agency controlled corporations", "finra", "pcaob", "msrb", "self regulatory organizations", "what is an sro", "private corporations", "exchanges and clearing agencies"],
    a: "Some private bodies exercise delegated government power under SEC oversight: FINRA (brokers), the PCAOB (auditors), the MSRB (municipal securities), and the stock exchanges and clearing agencies. RegCollect tracks them from SEC notices in the Federal Register; it does not read their own websites.", next: ["What is the private delegation issue?"] },
  { id: "charts", q: ["how do i make a chart", "charts", "graph", "visualize", "chart builder", "how do charts work", "download a chart"],
    a: "Open an agency, choose the Charts tab, then pick a chart (stacked bars or lines over time, totals, or share of total), what to break it down by, the filters, and the dates. Download it as PNG, SVG, or CSV. Or just tell me, for example “chart SEC sanctions by month” or “pie chart of FDA outcomes”." },
  { id: "chart_export", q: ["export chart", "save chart", "png", "svg", "csv of chart", "chart table", "chart numbers"],
    a: "Under the chart controls are buttons for PNG, SVG, and CSV, and a button to show the numbers as a table." },
  { id: "research", q: ["how does research work", "research page", "how do i search", "search tips", "advanced search", "how to search better", "search help"],
    a: "On <a href=\"#research\">Research</a>, describe what you want in plain English. RegCollect recognizes agencies, dates, sanctions, constitutional issues, statutes, case names, outcomes, and ratings, and ranks every action by relevance using related words, word forms, and typo tolerance. The chips above the results show how it read you; click × to drop any. If nothing matches every part, it drops the rarest part and says so.", next: ["What does strict match do?", "How do I download results?"] },
  { id: "strict", q: ["strict match", "every recognized part", "best matches first", "match mode", "exact match"],
    a: "“Best matches first” ranks everything by relevance. “Every recognized part” keeps only actions that match every recognized agency, issue, sanction, statute, or rating in your request." },
  { id: "related_matches", q: ["related matches", "weaker matches", "why are there related matches", "nothing silently left out"],
    a: "Below the strong matches, RegCollect keeps weaker “related matches” in a folded panel so nothing is silently left out." },
  { id: "research_period", q: ["period searched", "search older years", "search since 2015", "search all history", "why is search only 12 months", "search a specific year"],
    a: "Research searches the past 12 months by default. Choose another period on the left (a single year, or everything since 2015, which is a larger download). Mentioning a year in your request also widens it." },
  { id: "group_by", q: ["group results", "group by", "timeline", "by week", "by agency", "by issue"],
    a: "Above the results, “Group by” can sort them into groups by lawfulness, impact, agency, issue, sanction, kind, or week. Add “as a timeline” or “by agency” to your request to do this automatically." },
  { id: "table_view", q: ["table view", "show as a table", "spreadsheet view", "sort columns"],
    a: "Choose “Show as: Table” above the results (or add “as a table” to your request). Click any column heading to sort; click again to reverse." },
  { id: "csv", q: ["download results", "export results", "csv", "download csv", "excel", "spreadsheet"],
    a: "In Research, “Download CSV” saves every match, with the rating, impact, issues, possible issues, court rulings, statutes cited, and whether the full text was read." },
  { id: "copy_link", q: ["share a search", "copy link", "save a search", "bookmark", "send a search to someone"],
    a: "Every Research search lives in the page address. Use “Copy link” to share or bookmark it." },
  { id: "quick_search", q: ["quick search", "search bar", "keyboard shortcut", "slash key", "search everything"],
    a: "The search box at the top searches everything; press / to jump to it from anywhere. It opens Research with your request." },
  { id: "issues_page", q: ["constitutional issues page", "issues page", "where are the flags", "all flagged actions", "list of violations"],
    a: "The <a href=\"#issues\">Constitutional issues</a> page lists every rated action from almost certainly to likely unlawful. Click a box to narrow by rating, choose an impact level, pick a kind of issue, or show possible issues that weren't rated.", go: "#issues" },
  { id: "since", q: ["what's new since", "change the date", "since my last visit", "new since", "pick a starting date", "how does what's new work"],
    a: "RegCollect remembers your last visit and shows what was published since then, plus items that arrived late. Use the date button at the top right to pick another starting date, or tell me “show what's new since October 1”." },
  { id: "mark_read", q: ["mark everything as read", "mark all read", "caught up", "reset new", "clear new items"],
    a: "Done. Everything up to now is marked as read.", action: "markread" },
  { id: "sync", q: ["sync", "another computer", "another browser", "my phone", "log in elsewhere", "move my account", "sync code"],
    a: "Click your username at the top right and copy the sync code. On the other browser, paste it on the welcome screen. Your username and last visit carry over." },
  { id: "username", q: ["username", "password", "account", "sign in", "log in", "switch user", "log out"],
    a: "There's no password: your username just lets RegCollect remember your last visit in this browser. Use the account button at the top right to switch users or copy a sync code." },
  { id: "privacy", q: ["privacy", "is my data private", "what do you store", "tracking", "cookies", "where does my data go", "do you send anything"],
    a: "Everything stays in your browser: your username, dates, searches, reviews, and our conversation. RegCollect has no server, no trackers, and no outside services." },
  { id: "updates", q: ["when does it update", "how often", "update schedule", "why is today missing", "data freshness", "last update", "when was the last run"],
    a: "The collector runs every morning (about 7:20 a.m. Eastern) and the history and full-text reader runs every two hours. The Federal Register publishes on business days. See <a href=\"#coverage#runs\">recent runs</a>." },
  { id: "loading", q: ["slow", "loading forever", "takes long", "page is slow", "why is it slow"],
    a: "Searching everything since 2015 downloads many month files, so the first search over a long period can take a few seconds. After that the files are cached. The past 12 months loads fastest." },
  { id: "mobile", q: ["phone", "mobile", "tablet", "small screen"],
    a: "RegCollect works on phones and tablets; the menu scrolls sideways and I sit in the bubble at the bottom right." },
  { id: "print", q: ["print", "printing", "pdf"],
    a: "Use your browser's print command for any page. For tables of results, the CSV download is usually more useful." },
  { id: "legal_advice", q: ["is this legal advice", "can i rely on this", "is a flag a legal opinion", "disclaimer", "accuracy warning"],
    a: "No. A flag is an automated screen that marks an issue worth a lawyer's review; it is not a legal conclusion, and an unflagged action can still raise issues. The doctrine memos are drafts awaiting review, and every citation should be verified." },
  { id: "who_made", q: ["who made this", "who built this", "who created regcollect", "who runs this", "who owns this", "who made regcollect", "is this a government site", "who is behind this"],
    a: "RegCollect is an independent project. It isn't a government website and isn't affiliated with any agency. Its code, data, and rubric are public in the <a href=\"https://github.com/JoeDonnelly840/Agency-Repository-Public-\" rel=\"noopener\">repository</a>, so anyone can check how it works." },
  { id: "source_code", q: ["source code", "github", "repository", "how is it built", "open source", "technology"],
    a: "The code is in the <a href=\"https://github.com/JoeDonnelly840/Agency-Repository-Public-\" rel=\"noopener\">public repository</a>: a small Python collector run by GitHub Actions, and a static website with no outside libraries." },
  { id: "add_agency", q: ["add an agency", "more agencies", "track another agency", "why isn't my agency here", "new agencies"],
    a: "More federal agencies can be added in <code>collector/config.py</code>; each needs its Federal Register and Regulations.gov names. State agencies are planned for a later version." },
  { id: "states", q: ["state agencies", "state regulators", "state law", "states"],
    a: "State agencies are planned for a future version. Items already record a jurisdiction so they can be added alongside the federal ones." },

  // ------------------------------------------------------------------ coverage
  { id: "coverage", q: ["what do you track", "what sources", "where does the data come from", "data sources", "what do you read"],
    a: "RegCollect reads the Federal Register (every tracked agency and the President, since 2015, including full-text searches and full reads of important documents), Regulations.gov, the SEC's litigation and administrative-proceeding feeds, NLRB, FDA, and CFPB press feeds, and FDA recall reports. See <a href=\"#coverage\">What we track</a>.", next: ["What don't you track?", "How far back does history go?"] },
  { id: "not_tracked", q: ["what don't you track", "what is missing", "gaps", "blind spots", "limitations", "what can't you see"],
    a: "The main gaps: FTC and FCC press releases (their sites refuse automated readers), NLRB Board and judge decisions, DOL and EPA enforcement databases, FERC and HHS-OIG enforcement, FINRA's own database, court dockets, and anything an agency never publishes. See <a href=\"#coverage#not\">Not tracked</a>." },
  { id: "ftc_fcc", q: ["why no ftc press releases", "why no fcc press releases", "ftc missing", "fcc missing"],
    a: "The FTC and FCC websites refuse automated readers in their robots.txt files, and RegCollect respects that. Their orders still appear when published in the Federal Register." },
  { id: "history", q: ["how far back", "history", "backfill", "2015", "older actions", "historical data"],
    a: "History reaches back to January 1, 2015, for the Federal Register, Regulations.gov, and FDA recall reports. It fills in automatically, newest months first; see <a href=\"#coverage#history\">progress</a>. The SEC and agency press feeds only keep recent items." },
  { id: "dates", q: ["how are dates chosen", "what date is shown", "action date", "signing date", "publication date", "date basis"],
    a: "Actions are dated by the agency's own action: the signing date when the Federal Register records one, otherwise the publication, posting, or release date; FDA recalls use FDA's classification date. Nothing is dated by when RegCollect collected it." },
  { id: "late_postings", q: ["late postings", "items from before my last visit", "why old items in new"],
    a: "If an older action reached RegCollect after your last visit (for example, a late posting), it's included in “what's new” so you don't miss it." },
  { id: "rules_legal", q: ["is this legal", "scraping", "terms of service", "robots.txt", "do you hammer websites", "politeness", "is it safe for the websites"],
    a: "The collector uses official APIs and published feeds only, checks robots.txt, sends one request at a time with pauses, caps requests per run, obeys “slow down” replies, and never submits anything. Any address not on its allow-list is refused in code." },
  { id: "fulltext", q: ["do you read the full text", "only titles", "full document", "whole document", "full text reading", "do you search the whole document"],
    a: "Yes. RegCollect asks the Federal Register's full-text search about legal terms (IEEPA, Chevron, RFRA, the Seventh Amendment, and about 30 more) and reads the plain text of the most important documents in full: presidential documents, flagged actions, and significant rules. It keeps only short passages around the phrases its tests look for. Each flag says which elements came from the full text. History is being read back to 2015; see <a href=\"#coverage#fulltext\">progress</a>.", next: ["Why don't you read everything?"] },
  { id: "fulltext_why_not_all", q: ["why don't you read everything", "read all documents", "why not every document"],
    a: "Reading every one of 200,000+ documents would take weeks of polite requests. RegCollect reads the ones most likely to matter first and uses full-text searches to find the rest. Regulations.gov attachments and press releases are still rated from titles and summaries." },
  { id: "passages", q: ["passages", "show passages", "evidence", "quotes from the document", "what did the document say"],
    a: "Open “Why flagged” on an action and click “Show passages from the document”. You'll see the short passages RegCollect kept from the full text, and which legal terms the full-text search found." },

  // ------------------------------------------------------------------ the rubric
  { id: "how_rated", q: ["how are actions rated", "how does the rating work", "rubric", "methodology", "how do you decide", "how are flags made", "scoring"],
    a: "Each kind of issue has a memo with a legal test broken into elements. RegCollect looks for each element in the title, summary, and full text, and finds the strength of the precedent: a <strong>direct holding</strong>, a <strong>close analogy</strong>, or an <strong>open question</strong>. Together they give one rating, <strong>lawfulness</strong>: almost certainly, very likely, or likely unlawful. The two higher levels need the key elements in the document's operative text (or a court ruling); passages elsewhere in the full text can support Likely. A court ruling on the action itself sets the rating directly. <a href=\"#methods\">Full rubric</a>.",
    next: ["What does very likely mean?", "What is a possible issue?", "Does impact affect the rating?"] },
  { id: "levels", q: ["lawfulness", "constitutionality", "rating levels", "what does likely mean", "what does very likely mean", "what does near certain mean", "what does likely unlawful mean", "what does very likely unlawful mean", "what does almost certainly unlawful mean", "almost certainly unlawful", "almost certainly unconstitutional", "difference between likely and very likely", "difference between the ratings", "red flag", "what is a red flag", "orange flag", "yellow flag", "red orange yellow", "colors", "what do the colors mean"],
    a: "There is one scale, lawfulness. <span class=\"c3\">Near certain</span> (almost certainly unlawful): a Supreme Court ruling against this very action, or a direct holding against the practice with every element of the test in the document's summary or operative text. <span class=\"c2\">Very likely</span>: an appeals-court ruling against the action, a direct holding with at least half the elements, or a close analogy with every element, again in the summary or operative text. <span class=\"c1\">Likely</span>: the gate elements are present and the law points toward a violation, but the precedent is less direct, fewer elements were found, or the key elements appear only in passages of the full text. A district-court ruling against the action also gives Likely. Weaker matches are listed as possible issues." },
  { id: "possible", q: ["possible issue", "not rated", "what is a possible issue", "unrated", "why isn't this rated", "screened"],
    a: "A possible issue is one where the document's wording touches a legal issue but the “gate” elements needed for a rating weren't found, or where a Supreme Court holding upheld the very practice (the flag says which). It isn't counted as a rating, but it's a lead: many become rated once RegCollect reads the full text, and a lawyer may see more than the screen does. <a href=\"#issues?poss=1\">See possible issues</a>.", next: ["What are gate elements?"] },
  { id: "gates", q: ["gate elements", "gate", "required elements", "what are elements", "elements of the test", "checklist"],
    a: "Each memo breaks its legal test into elements, and marks the essential ones as gates. All gates must appear before an issue is rated; the share of all elements found then helps set the level. Open “Why flagged” to see the checklist." },
  { id: "precedent", q: ["precedent strength", "direct holding", "close analogy", "open question", "tiers", "tier 1 tier 2 tier 3"],
    a: "Every memo sorts its precedent into the same three levels, always in this order: <strong>direct holding</strong> (a court has held this practice unlawful), <strong>close analogy</strong> (a Supreme Court holding applies closely, or an appeals court held the same practice unlawful), and <strong>open question</strong>. Memos without a direct holding say so instead of skipping a level." },
  { id: "weighed", q: ["weighed factors", "counter indicators", "counter-indicators", "what lowers a rating", "why was the rating lowered"],
    a: "Weighed factors, such as a contrary holding or a closely regulated industry, lower a rating one step each but never below Likely. A court ruling that upheld the action counts the same way. A few factors remove the rating and leave a possible issue that says why, such as a Supreme Court holding that upheld the very practice (FCC forfeiture orders after FCC v. AT&T, 2026). A settlement is only noted." },
  { id: "settlements", q: ["settlement", "settled cases", "does a settlement lower the rating", "consent order rating"],
    a: "No. A settlement is noted but doesn't lower the rating: people settle out of fear or cost, and a settlement doesn't cure an unconstitutional forum." },
  { id: "contrary", q: ["contrary ruling", "court upheld it", "courts can be wrong", "does a contrary holding cap the rating"],
    a: "A contrary holding lowers the rating one step instead of capping it, and the flag says why. Courts can be wrong, so the issue stays visible." },
  { id: "today_law", q: ["today's law", "formerly constitutional", "lawful at the time", "at the time", "old actions", "chevron era rules", "rated under current law"],
    a: "Every action is rated under the law as it stands today. If it was lawful under the precedent at the time (for example, a rule that relied on Chevron before Loper Bright), the flag adds a note saying so." },
  { id: "impact", q: ["impact", "what is impact", "lower impact", "significant impact", "serious impact", "seriousness", "impact points"],
    a: "Impact notes how much is at stake: points for the sanction (up to 4), money (up to 3), and reach (up to 3). <strong>Lower Impact</strong> is 1 to 3 points, <strong>Significant Impact</strong> 4 to 6, <strong>Serious Impact</strong> 7 or more. It's shown as plain text and never affects the rating." },
  { id: "impact_score", q: ["does impact affect the rating", "is impact part of the score", "why isn't impact colored"],
    a: "No. The rating measures only whether an action is likely unlawful, not how big it is. Impact is shown for context, in plain text, and doesn't change ratings or the order of results." },
  { id: "rulings", q: ["court rulings", "known rulings", "has a court ruled", "struck down actions", "actions courts held unlawful", "what other rulings do you track", "which rulings do you track", "what rulings do you track", "list of rulings"],
    a: "When a court has ruled on a specific action, that ruling sets the rating: Supreme Court, almost certainly; court of appeals, very likely; district court, likely. Examples include the IEEPA tariff orders (Learning Resources), the Clean Power Plan (West Virginia v. EPA), and the CDC eviction moratorium. See <a href=\"#methods#rulings\">Known rulings</a>." },
  { id: "statutory_vs_constitutional", q: ["statutory or constitutional", "is exceeding authority unconstitutional", "why are statutory holdings included", "ultra vires"],
    a: "RegCollect has one scale, lawfulness. Some issues are constitutional (the jury right, appointments, free exercise); others concern power the executive was never granted (the major questions doctrine, the IEEPA tariffs, the eviction moratorium). The executive has only the powers the Constitution and Congress give it, so acting without them is unlawful, and each flag's label says which kind of issue it is." },
  { id: "why_unlawful", q: ["why unlawful instead of unconstitutional", "why does it say unlawful", "unlawful vs unconstitutional", "difference between unlawful and unconstitutional", "is unlawful the same as unconstitutional"],
    a: "“Unlawful” covers both kinds of defect RegCollect screens for: violating the Constitution, and acting without power the Constitution or Congress granted. One scale keeps them together; each flag's label names the issue. RegCollect doesn't screen ordinary statutory or procedural claims (for example, arbitrary-and-capricious review)." },
  { id: "why_few", q: ["why so few flags", "why only a few rated", "why are there no red flags", "too few violations", "why so many possible issues"],
    a: "A rating needs the elements of a legal test, not just a keyword. Most documents have only a title and short summary, so many issues stay possible until the full text is read. Each morning RegCollect reads new important documents in full, and it is working back through history; ratings rise as it does." },
  { id: "why_many", q: ["too many flags", "false positive", "this flag is wrong", "wrong rating", "rating seems off", "disagree"],
    a: "Open “Why flagged” and record your view (agree, higher, lower, or not an issue). Download your reviews from the <a href=\"#methods#improve\">Methodology</a> page and add them to the repository; each one becomes a permanent test of the rubric.", next: ["How can RegCollect get more accurate?"] },
  { id: "accuracy", q: ["how can regcollect get more accurate", "improve accuracy", "make it an expert", "training", "validation", "how accurate is it"],
    a: "Three ways: more full-text reading (now running daily and through history), a growing list of court rulings on specific actions, and your reviews. Reviewed actions become test cases, so the rubric can be tuned without losing ground. Agreement with human reviewers will be measured once enough reviews exist." },
  { id: "draft", q: ["draft memos", "who reviewed the memos", "are the memos reviewed", "review status"],
    a: "The doctrine memos are drafts awaiting review by a lawyer or law-trained reader. The Methodology page and DOCTRINE.md show the review status." },
  { id: "triggers", q: ["triggered by", "what triggered this flag", "trigger words"],
    a: "“Triggered by” lists the words that led RegCollect to check an issue. A trigger alone never produces a rating; the elements of the test do." },
  { id: "tobacco", q: ["tobacco complaints", "fda tobacco penalties", "why are tobacco cases possible issues", "civil money penalty complaints"],
    a: "FDA's tobacco-retailer penalty complaints are decided in-house, but the claims (selling to minors) lack an obvious common-law analogue, so after Jarkesy the jury question is open. They're listed as possible issues, not rated." },
  { id: "sro_possible", q: ["why are sro filings possible issues", "immediately effective filings", "private delegation rating"],
    a: "Immediately effective rule filings by exchanges and FINRA raise an open private-delegation question, but there are thousands and the Supreme Court upheld a subordinate private body in Consumers' Research (2025), so they're listed as possible issues rather than rated." },
  { id: "ieepa_rated", q: ["ieepa tariffs rating", "are the tariffs unconstitutional", "why are tariff orders red", "learning resources tariffs"],
    a: "In Learning Resources v. Trump (Feb. 20, 2026) the Supreme Court held that IEEPA does not authorize tariffs. Orders that imposed or modified IEEPA tariffs are rated almost certainly unlawful. Tariffs under Section 232 or 301 are checked separately and aren't covered by that holding." },
  { id: "chevron_rated", q: ["chevron rules rating", "rules relying on chevron", "loper bright effect"],
    a: "Rules that rested on Chevron deference are rated under today's law, no higher than Likely unlawful: Loper Bright (2024) overruled Chevron and held that courts, not agencies, decide what statutes mean. The flag notes that the rule stood on governing law when issued, and that Loper Bright didn't reopen past cases that upheld rules under Chevron. Documents published after Loper Bright aren't rated for Chevron reliance." },
  { id: "review_buttons", q: ["your view buttons", "record my view", "agree button", "review a flag", "my reviews", "download reviews"],
    a: "Each flag has “Your view” buttons. Your choices stay in this browser; download them from the <a href=\"#methods#improve\">Methodology</a> page." },
  { id: "rename_labels", q: ["rename the ratings", "change the labels", "different words for ratings"],
    a: "The rating names live in one place, <code>collector/flags.py</code> (SCALES). Change them there and every page follows." },

  // ------------------------------------------------------------------ glossary
  { id: "g_alj", q: ["what is an alj", "administrative law judge", "agency judge", "in house judge"], a: "An administrative law judge (ALJ) is an agency employee who presides over hearings and issues initial decisions, usually reviewable by the agency's head or board. Lucia (2018) held SEC ALJs are officers who must be properly appointed." },
  { id: "g_oip", q: ["order instituting proceedings", "oip", "what is an oip"], a: "An order instituting proceedings (OIP) is how the SEC starts an in-house administrative case, or records a settlement of one." },
  { id: "g_nal", q: ["notice of apparent liability", "nal", "fcc forfeiture"], a: "A notice of apparent liability (NAL) is the FCC's proposed fine. A forfeiture order follows if the party doesn't pay or prevail. FCC v. AT&T (2026) held these don't violate the Seventh Amendment." },
  { id: "g_consent", q: ["consent order", "consent decree", "what is a settlement order"], a: "A consent order (or decree) records a settlement: the party agrees to terms, often without admitting or denying the allegations." },
  { id: "g_cd", q: ["cease and desist", "cease-and-desist order"], a: "A cease-and-desist order directs a party to stop conduct and not repeat it. Agencies can issue them in-house." },
  { id: "g_disgorgement", q: ["disgorgement", "what is disgorgement"], a: "Disgorgement requires giving up profits from wrongdoing. Liu v. SEC (2020) limited it to net profits awarded for victims." },
  { id: "g_cmp", q: ["civil money penalty", "cmp", "civil penalty"], a: "A civil money penalty is a punitive fine imposed for violating a statute or rule. Tull and Jarkesy treat it as a legal remedy that can carry a jury right." },
  { id: "g_rule", q: ["rule", "what is a rule", "regulation", "what is a regulation", "rules and regulations", "legislative rule"], a: "Under the APA, a rule is an agency statement of general or particular applicability and future effect that implements, interprets, or prescribes law or policy (5 U.S.C. 551(4)). Legislative rules bind the public and usually go through notice and comment; interpretive rules and policy statements don't. RegCollect files proposed rules, final rules, and self-regulatory rule filings under Rulemaking." },
  { id: "g_eo", q: ["executive order", "what is an executive order", "eo", "executive orders"], a: "An executive order is a numbered written directive from the President, published in the Federal Register. It needs a source of power in the Constitution or a statute (Youngstown, 1952): it can direct the executive branch, but it can't make law for the public without that power. RegCollect screens every one." },
  { id: "g_proclamation", q: ["proclamation", "what is a proclamation", "proclamations", "difference between an executive order and a proclamation", "executive order vs proclamation", "proclamation vs executive order"], a: "A proclamation is a presidential document usually addressed to the public, while an executive order is usually directed to the executive branch; both are numbered and published in the Federal Register, and both need a source of power in the Constitution or a statute. Many proclamations are ceremonial (observances), but some carry legal force: tariffs under Section 232, entry restrictions under section 212(f), national monuments, and emergency declarations." },
  { id: "g_memorandum", q: ["presidential memorandum", "what is a memorandum", "memorandum", "memoranda"], a: "A presidential memorandum directs agencies much like an executive order but isn't numbered, and only some are published in the Federal Register. Its legal force depends, like an order's, on the power behind it." },
  { id: "g_notice", q: ["notice", "what is a notice", "federal register notice", "other notices"], a: "Federal Register notices announce things that aren't rules: meetings, applications, information collections, orders, and decisions. RegCollect sorts each by what it does, so an enforcement order published as a notice is filed under Enforcement." },
  { id: "g_flag", q: ["flag", "what is a flag", "what does flagged mean", "flagged"], a: "A flag marks a legal issue RegCollect found in an action. A rated flag shows how likely the action is unlawful (likely, very likely, or near certain); a possible issue is a weaker match worth a look. Open “Why flagged” on any action for the reasoning." },
  { id: "g_ratification", q: ["ratification", "ratify", "does ratification cure an appointment defect", "ratifying appointments"], a: "When a properly appointed official ratifies an earlier action or appointment, several courts of appeals have held that this can cure an Appointments Clause defect going forward. RegCollect treats ratifications as cures, so a ratifying action isn't flagged." },
  { id: "g_nprm", q: ["nprm", "notice of proposed rulemaking", "proposed rule"], a: "A notice of proposed rulemaking (NPRM) publishes a proposed rule for public comment before the agency adopts a final rule." },
  { id: "g_anprm", q: ["anprm", "advance notice of proposed rulemaking"], a: "An advance notice of proposed rulemaking (ANPRM) asks for input before an agency writes a proposal." },
  { id: "g_ifr", q: ["interim final rule", "ifr", "rule without comment"], a: "An interim final rule takes effect before public comment, usually under the APA's good-cause exception, with comments taken afterward." },
  { id: "g_dfr", q: ["direct final rule"], a: "A direct final rule takes effect automatically unless the agency receives significant adverse comment." },
  { id: "g_final", q: ["final rule", "what is a final rule"], a: "A final rule is a binding regulation adopted after notice and comment and published in the Federal Register, then codified in the Code of Federal Regulations." },
  { id: "g_guidance", q: ["guidance", "policy statement", "interpretive rule", "what is guidance"], a: "Guidance documents, policy statements, and interpretive rules explain how an agency reads the law. They don't need notice and comment, but they can't bind the public as legislative rules do." },
  { id: "g_significant", q: ["significant rule", "executive order 12866", "eo 12866", "economically significant", "oira"], a: "Under Executive Order 12866, OIRA (in OMB) reviews significant rules. Economically significant rules have $100 million or more in annual effect (a 2023 order raised this to $200 million; that order was revoked in January 2025)." },
  { id: "g_major_rule", q: ["major rule", "congressional review act", "cra"], a: "The Congressional Review Act lets Congress disapprove new rules by joint resolution. A “major rule” (about $100 million or more in effect) must wait 60 days before taking effect." },
  { id: "g_fr", q: ["federal register", "what is the federal register"], a: "The Federal Register is the government's daily journal: proposed and final rules, notices, and presidential documents. RegCollect's main source." },
  { id: "g_cfr", q: ["cfr", "code of federal regulations"], a: "The Code of Federal Regulations collects final rules in force, organized by title and part." },
  { id: "g_regsgov", q: ["regulations.gov", "what is regulations.gov", "docket"], a: "Regulations.gov holds rulemaking dockets: proposals, supporting documents, and public comments. A docket ID ties together the documents in one proceeding." },
  { id: "g_rin", q: ["rin", "regulation identifier number"], a: "A Regulation Identifier Number (RIN) tracks a rulemaking across the Unified Agenda and the Federal Register." },
  { id: "g_apa", q: ["apa", "administrative procedure act", "notice and comment", "arbitrary and capricious"], a: "The Administrative Procedure Act sets how agencies make rules (notice and comment) and how courts review them: actions that are arbitrary and capricious, contrary to law, or beyond statutory authority are set aside." },
  { id: "g_good_cause", q: ["good cause exception", "good cause"], a: "The APA lets agencies skip notice and comment when it would be “impracticable, unnecessary, or contrary to the public interest.” Courts read the exception narrowly." },
  { id: "g_chevron", q: ["chevron", "what is chevron", "chevron deference", "what happened with chevron", "what happened to chevron", "is chevron still good law", "is chevron overruled", "chevron overruled"], a: "Chevron (1984) told courts to defer to an agency's reasonable reading of an ambiguous statute. Loper Bright (2024) overruled it: courts now decide statutory meaning themselves, giving agency views only the weight their reasoning earns. RegCollect rates rules that rested on Chevron no higher than Likely unlawful, with a note that they were lawful under the precedent at the time.", next: ["How many actions relied on Chevron since 2015?", "What is Loper Bright?"] },
  { id: "g_skidmore", q: ["skidmore", "skidmore deference"], a: "Under Skidmore (1944), an agency's interpretation gets weight according to its thoroughness, reasoning, and consistency. After Loper Bright, Skidmore respect is what remains." },
  { id: "g_auer", q: ["auer", "auer deference", "kisor"], a: "Auer deference to an agency's reading of its own regulation survives, but Kisor (2019) limited it to genuinely ambiguous rules and authoritative, expertise-based readings." },
  { id: "g_mqd", q: ["what is the major questions doctrine", "major questions doctrine", "major questions"], a: "The major questions doctrine requires clear congressional authorization before an agency decides a question of vast economic or political significance (West Virginia v. EPA, 2022; Biden v. Nebraska, 2023)." },
  { id: "g_nondelegation", q: ["nondelegation", "intelligible principle", "what is nondelegation"], a: "The nondelegation doctrine bars Congress from handing away legislative power; a delegation is valid if it lays down an intelligible principle. Consumers' Research (2025) upheld the Universal Service Fund under that test." },
  { id: "g_youngstown", q: ["youngstown", "jackson categories", "three categories", "presidential power framework"], a: "Under Justice Jackson's Youngstown framework, presidential power is greatest when acting with Congress's authorization, uncertain in its silence, and weakest when acting against its will." },
  { id: "g_ieepa", q: ["what is ieepa", "international emergency economic powers act"], a: "IEEPA (1977) lets the President regulate certain economic transactions after declaring a national emergency about an unusual and extraordinary foreign threat. Learning Resources (2026) held it doesn't authorize tariffs." },
  { id: "g_nea", q: ["national emergencies act", "national emergency declaration"], a: "The National Emergencies Act governs how the President declares national emergencies, which unlock statutory emergency powers like IEEPA. Congress can end an emergency by joint resolution." },
  { id: "g_232", q: ["section 232", "national security tariffs", "trade expansion act"], a: "Section 232 lets the President adjust imports that threaten national security after a Commerce investigation. Algonquin (1976) read it broadly, and Learning Resources didn't address it." },
  { id: "g_301", q: ["section 301", "trade act section 301", "ustr"], a: "Section 301 lets the U.S. Trade Representative respond to unfair foreign trade practices, including with tariffs, after an investigation." },
  { id: "g_212f", q: ["212(f)", "entry ban", "travel ban", "trump v hawaii"], a: "INA section 212(f) lets the President suspend entry of classes of noncitizens. Trump v. Hawaii (2018) upheld a proclamation under it." },
  { id: "g_ica", q: ["impoundment control act", "impoundment", "rescission request", "deferral"], a: "The Impoundment Control Act lets the President propose rescissions or deferrals of appropriated funds, but not simply withhold them. GAO reports on violations." },
  { id: "g_appropriations", q: ["appropriations clause", "power of the purse"], a: "The Appropriations Clause says no money may be drawn from the Treasury but by appropriation made by law. CFPB v. CFSA (2024) upheld the CFPB's funding mechanism under it." },
  { id: "g_seventh", q: ["seventh amendment", "right to a jury", "jury trial right"], a: "The Seventh Amendment preserves the jury right in suits at common law. Jarkesy (2024) held it applies to SEC civil-penalty claims for securities fraud, so they can't be decided in-house." },
  { id: "g_public_rights", q: ["public rights", "public rights exception"], a: "The public-rights exception lets Congress assign some matters (historically customs, immigration, public lands, benefits, and taxes) to agencies without a jury. Jarkesy narrowed it for claims resembling common-law actions." },
  { id: "g_article3", q: ["article iii", "article 3"], a: "Article III vests the judicial power in federal courts with life-tenured judges. Agency adjudication of private-right claims can intrude on it." },
  { id: "g_appointments", q: ["what is the appointments clause", "appointments clause", "principal and inferior officers"], a: "The Appointments Clause requires principal officers to be nominated by the President and confirmed by the Senate; inferior officers may be appointed by the President, courts, or department heads. Lucia and Arthrex apply it to agency judges." },
  { id: "g_removal", q: ["removal power", "humphrey's executor", "can the president fire commissioners", "independent agencies"], a: "Humphrey's Executor (1935) let Congress protect commissioners from removal. Seila Law (2020) struck the CFPB director's protection, and Trump v. Slaughter (2026) overruled Humphrey's for the FTC. Trump v. Cook treated the Federal Reserve differently." },
  { id: "g_unitary", q: ["unitary executive", "unitary executive theory"], a: "The unitary executive theory holds that the President controls all executive power, including removal of officers who exercise it. Recent decisions (Seila Law, Slaughter) moved doctrine in that direction." },
  { id: "g_19b", q: ["19(b)", "section 19(b)", "immediately effective", "sro rule filing", "19b-4"], a: "Section 19(b) of the Securities Exchange Act requires self-regulatory organizations to file rule changes with the SEC. Some, like fee changes, are immediately effective under 19(b)(3)(A); the SEC can suspend them within 60 days." },
  { id: "g_free_exercise", q: ["free exercise test", "what is the test for free exercise", "smith test", "religion test", "strict scrutiny for religion"], a: "Under Smith (1990), a neutral, generally applicable law gets rational-basis review even if it burdens religion. A law that targets religion, isn't neutral, allows individualized exemptions (Fulton), or treats comparable secular activity better (Tandon) must survive strict scrutiny (Lukumi). For federal action, RFRA requires strict scrutiny of any substantial burden regardless.", next: ["What is RFRA?", "What is RLUIPA?"] },
  { id: "g_rfra", q: ["what is rfra", "religious freedom restoration act", "rfra test"], a: "RFRA (1993) bars the federal government from substantially burdening religious exercise, even by a neutral and generally applicable rule, unless it's the least restrictive means of serving a compelling interest. It doesn't apply to states (City of Boerne), but it binds every federal agency (Hobby Lobby; Little Sisters)." },
  { id: "g_rluipa", q: ["what is rluipa", "religious land use and institutionalized persons act", "prisoner religion"], a: "RLUIPA (2000) applies RFRA's strict-scrutiny test to land-use regulation and to prisons and other institutions that receive federal funds (Holt v. Hobbs). Federal agencies matter when they set conditions on those programs." },
  { id: "g_establishment", q: ["establishment clause", "lemon test", "government and religion"], a: "The Establishment Clause bars government establishment of religion. Kennedy v. Bremerton (2022) replaced the Lemon test with history and tradition; Catholic Charities (2025) bars line-drawing between denominations." },
  { id: "g_commercial_speech", q: ["commercial speech", "central hudson", "advertising rules"], a: "Restrictions on truthful commercial speech face intermediate scrutiny under Central Hudson (1980), and heightened scrutiny when content- or speaker-based (Sorrell)." },
  { id: "g_zauderer", q: ["zauderer", "compelled disclosure", "warning labels", "compelled speech"], a: "Zauderer allows compelled commercial disclosures that are purely factual and uncontroversial and reasonably related to preventing deception. NIFLA (2018) applies heightened scrutiny to other compelled statements." },
  { id: "g_prior_restraint", q: ["prior restraint", "gag order", "no-deny policy", "neither admit nor deny"], a: "Prior restraints are presumptively invalid. Agency settlement terms barring public denials have so far been upheld as voluntary waivers (Romeril; Powell), though the SEC rescinded its no-deny policy in May 2026." },
  { id: "g_admin_search", q: ["administrative search", "inspection warrant", "closely regulated industry", "burger exception"], a: "Administrative inspections generally need a warrant (See v. Seattle), and records demands need a chance for precompliance review (Patel). Closely regulated industries are an exception (Burger)." },
  { id: "g_takings", q: ["takings", "what is a taking", "cedar point", "just compensation"], a: "The Takings Clause requires just compensation when government takes property. A regulation granting a right to physically enter property is a per se taking (Cedar Point, 2021)." },
  { id: "g_due_process", q: ["procedural due process", "mathews v eldridge", "fair notice"], a: "Due process requires notice and an opportunity to be heard, weighed under Mathews v. Eldridge, and fair notice of what conduct is forbidden before sanctions (FCC v. Fox)." },
  { id: "g_excessive", q: ["excessive fines clause", "excessive fines", "grossly disproportional"], a: "The Eighth Amendment bars fines grossly disproportional to the offense (Bajakajian). Civil forfeitures that partly punish are covered (Austin)." },
  { id: "g_equal", q: ["equal protection test", "strict scrutiny race", "sffa", "affirmative action rule"], a: "Federal racial classifications get strict scrutiny (Adarand) and are rarely upheld after SFFA (2023). Sex classifications need an exceedingly persuasive justification (United States v. Virginia)." },
  { id: "g_commandeering", q: ["anti-commandeering", "commandeering", "printz", "murphy v ncaa"], a: "The federal government may not command state officers (Printz) or legislatures (Murphy) to carry out federal policy." },
  { id: "g_spending_conditions", q: ["spending clause conditions", "conditions on grants", "coercive conditions", "dole test"], a: "Conditions on federal funds must be clear, related, and not coercive (South Dakota v. Dole; NFIB v. Sebelius). Conditions imposed by the executive without statutory authority raise a separate problem." },
  { id: "g_axon", q: ["axon", "challenge agency in court", "collateral challenge"], a: "Axon (2023) lets parties bring structural constitutional challenges to agency proceedings in federal district court without waiting for the agency to finish." },
  { id: "g_cfpb_funding", q: ["cfpb funding", "is the cfpb funding constitutional", "is the cfpb constitutional", "cfpb funding constitutional", "community financial services", "cfsa v cfpb", "appropriations clause cfpb"], a: "Yes, under current law. In CFPB v. Community Financial Services Ass'n of America (2024), the Supreme Court held 7 to 2 that the CFPB's funding, drawn from the Federal Reserve up to a cap Congress set, is an appropriation that satisfies the Appropriations Clause. RegCollect doesn't flag CFPB actions for their funding." },
  { id: "g_collins", q: ["collins v yellen", "remedy for removal violation", "does a removal defect void actions"], a: "Collins v. Yellen (2021) held that an unconstitutional removal restriction doesn't by itself void an agency's actions; the challenger must show it caused harm." },
  { id: "g_vacatur", q: ["vacatur", "vacated", "set aside", "what does vacate mean"], a: "A court vacates (sets aside) an unlawful agency action under the APA, so it has no effect. It may instead remand without vacatur, leaving the rule in place while the agency fixes it." },
  { id: "g_stay", q: ["stay", "what is a stay", "stay vs ruling", "preliminary injunction"], a: "A stay or preliminary injunction pauses an action pending litigation, based on a likelihood of success. RegCollect treats such rulings as somewhat weaker than final judgments." },
  { id: "g_universal", q: ["universal injunction", "nationwide injunction", "trump v casa"], a: "Trump v. CASA (2025) limited universal injunctions: federal courts generally may grant relief only to the parties before them, though APA vacatur and class actions remain available." },
  { id: "g_finra", q: ["what is finra", "finra discipline", "alpine securities"], a: "FINRA is a private self-regulatory organization that writes rules for and disciplines broker-dealers under SEC oversight. Alpine (D.C. Cir. 2024) held FINRA can't expel a member before SEC review." },
  { id: "g_pcaob", q: ["what is the pcaob", "free enterprise fund"], a: "The PCAOB registers, inspects, and disciplines auditors of public companies under SEC oversight. Free Enterprise Fund (2010) struck its two layers of removal protection." },
];
